def quarantine_historical_transfers(apps, schema_editor):
    import re
    Transfer = apps.get_model("domains", "DomainTransfer")
    Attempt = apps.get_model("domains", "DomainTransferAttempt")
    alias = schema_editor.connection.alias
    pending = []
    for row in Transfer.objects.using(alias).filter(submission_attempt__isnull=True).order_by("pk").values(
        "pk", "status", "domain_id", "user_id", "domain_name", "registrar_order_id",
        "domain__name", "domain__user_id", "domain__registrar_id",
    ).iterator(chunk_size=500):
        identifier = str(row["registrar_order_id"] or "")
        if (row["status"] == "completed" and re.fullmatch(r"[1-9][0-9]{0,18}", identifier)
                and row["domain_id"] and row["domain__name"] == row["domain_name"]
                and row["domain__user_id"] == row["user_id"] and row["domain__registrar_id"] == identifier):
            continue
        pending.append(Attempt(transfer_id=row["pk"], status="unknown", legacy_review_required=True,
                               subject={"legacy_original_status": row["status"]}))
        if len(pending) == 500:
            Attempt.objects.using(alias).bulk_create(pending, batch_size=500, ignore_conflicts=True)
            pending.clear()
    if pending:
        Attempt.objects.using(alias).bulk_create(pending, batch_size=500, ignore_conflicts=True)


